recipes.code:
{
  "inputs": [
    {
      "id": "verifox-api-key",
      "type": "promptString",
      "description": "Your Verifox API key (foxkey_...). Get 1,000 free credits at https://verifox.ai/dashboard/api",
      "password": true
    }
  ],
  "servers": {
    "email-verifier": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "verifox-mcp@1.2.1"
      ],
      "env": {
        "VERIFOX_API_KEY": "${input:verifox-api-key}"
      }
    }
  }
}
